local _, ns = ...
local L = ns.L

-- Options/Welcome.lua: What's New, by version (WN<id>_<n>), newest first; English beside Locales/enUS.lua.
L["WN48_1_TITLE"] = "Combined map and quest log"
L["WN48_1_TEXT"] = "The quest list beside the map, with the picked quest's text and rewards on two pages under it, as the Wrath-era map. Drag the map's corner to size it and the divider to widen the list. Off by default; turn on Classic combined map/quest in the options (/fcui), under Map, with the Classic style navigation bar."
L["WN48_2_TITLE"] = "Quest list text"
L["WN48_2_TEXT"] = "Quest list font size and Quest text font size make the map's quest lists and quest text bigger, and List on the game's parchment puts the list on the game's quest log page instead of dark stone. They start at the game's look; turn them on in the options (/fcui), under Map."
L["WN48_3_TITLE"] = "Guild tab like Era"
L["WN48_3_TEXT"] = "The guild tab follows Classic Era's layout: its column headers, the bar over the message of the day, the counts, the buttons and the Show Offline Members box stand where Era has them, and class names show in white."
L["WN48_4_TITLE"] = "Bank like Era"
L["WN48_4_TEXT"] = "The bank keeps Forever's bigger grid and takes Era's layout under it: a row of full-size bag slots, the purchase line, and your money on a strip across the bottom."
L["WN48_5_TITLE"] = "Territory in zone names"
L["WN48_5_TEXT"] = "A zone's territory, such as Alliance Territory, shows outside the capitals too, as in 1.x. To keep the game's names, uncheck Territory in zone names in the options (/fcui), under Other."
L["WN48_6_TITLE"] = "Classic layout spots"
L["WN48_6_TEXT"] = "The Classic layout button and the first-login setup put your player, target and focus frames and bars 4 and 5 where Classic Era has them. Nothing moves on its own: press Classic layout in the options window to use them."
L["WN48_7_TITLE"] = "Bottom bar"
L["WN48_7_TEXT"] = "The World Map button sits after the social button, as in Era, and the micro menu's art is Era's own, darker toward its right end, with the latency window, key ring and bags beside it where Era has them."
L["WN48_8_TITLE"] = "Smaller options"
L["WN48_8_TEXT"] = "The game's \"You received\" box for a rare drop, a won roll or an upgrade is hidden, as 1.x had none; Loot toast brings it back. Hide bag search box and Hide Clean Up button clear those off the bags. All three are off by default; turn them on in the options (/fcui), under Other and Bags. Map coordinates rows under Map are the game's own settings."
L["WN48_9_TITLE"] = "On retail"
L["WN48_9_TEXT"] = "The group finder eye moves round the minimap and sizes in our Edit Mode's minimap options, crit and haste show the game's own tooltips, and Hide map help button hides the map's tutorial button. It is off by default; turn it on in the options (/fcui), under Map."
L["WN48_10_TITLE"] = "Fixes"
L["WN48_10_TEXT"] = "The party debuff glow is a ring round the portrait, a page looted empty turns to the next, the group finder eye grows with the minimap and no longer errors or vanishes in Edit Mode, the Who list's column menu picks and sorts a column directly, and quest pages fill in late reward details. Inspecting a player's talents in a fight shows only our window, and a fight starting mid drag stops the window where it is."
L["WN47_1_TITLE"] = "Guild & Communities page"
L["WN47_1_TEXT"] = "The Guild & Communities window is a social page now: it carries the Friends, Who, Guild and Raid tabs in both its modes, and its small mode is the social window's size, with the ring and portrait."
L["WN47_2_TITLE"] = "Profiles as text"
L["WN47_2_TEXT"] = "Export and Import on the Profiles page: a profile as one line of text to copy to another account or a friend, and back into a new profile."
L["WN47_3_TITLE"] = "Menu Width"
L["WN47_3_TEXT"] = "The micro menu's edit dialog has a Menu Width slider beside Size: the row widens or narrows round buttons that keep their size. Size past 100% now widens the art with the row."
L["WN47_4_TITLE"] = "Social window fixes"
L["WN47_4_TEXT"] = "The social window stays put after a Who search, the status button under the title takes clicks, hidden micro buttons no longer open their windows from an empty seat."
L["WN47_5_TITLE"] = "Map in combat"
L["WN47_5_TEXT"] = "The world map is protected in a fight only while this addon's classic map lays it, so map addons work in combat with the classic map off."
L["WN46_1_TITLE"] = "Social window fixes"
L["WN46_1_TEXT"] = "The social window's Raid tab is back in its foot row on clients that have the game's new social system off, and the small tab under Recent Allies says Quick Join again instead of Raid. The window now drags by its title bar only, so the status button under the title takes clicks."
L["WN45_1_TITLE"] = "Collections on retail"
L["WN45_1_TEXT"] = "The classic Collections window is on retail too: mounts, pets with your battle team beside them, toys and heirlooms as book pages, campsites and appearances, each page with the game's own filters. Drag a preview to turn it, scroll over a creature to zoom, right-drag an appearance to move it; the reset button beside the arrows puts it back. Collections window is on by default, in the options (/fcui) under Character, spells, talents."
L["WN45_2_TITLE"] = "A search on every page"
L["WN45_2_TEXT"] = "Each options page has its own search box at the top right, which looks through that page only; the search at the top left still covers every page. Toggle none and Default toggles moved to the bottom right. Classic style windows is gone from All windows: every window is its own box now, and no row grays out because of another."
L["WN45_3_TITLE"] = "Statistics search"
L["WN45_3_TEXT"] = "A search box on the character window's Stats tab finds statistics by name or category. Off by default; turn it on in the options (/fcui), under Character, spells, talents."
L["WN45_4_TITLE"] = "Interface size"
L["WN45_4_TEXT"] = "The classic layout sets the game's UI Scale to Classic Era's size, 90% on most screens. Toggle none in the options sidebar now offers to put your old size back, with a check box in its confirm, and Default toggles offers Era's size while you are at another. Both confirms say to save a profile first to come back to your settings, and the FAQ page explains the size."
L["WN45_5_TITLE"] = "Who list off"
L["WN45_5_TEXT"] = "With Who list off, the Who tab on the social window and the Who side tab on the group finder open Forever's own Who list, a page of the finder; Listing and Browse go back to the classic pages. Hide Who tab takes the tab off the social window's foot. Off by default; turn it on in the options (/fcui), under Social."
L["WN45_6_TITLE"] = "Bags and bars"
L["WN45_6_TEXT"] = "Hide key ring art takes the key ring's art off the band. Off by default; turn it on in the options (/fcui), under Bags. On retail the reagent bag has its own picks under Bags: as key art, as squished bag art, a full slot or hidden. One bar turns nothing else on and lists its pairings under it, and the modern page arrows sit above the gryphon with Gryphons over bars."
L["WN45_7_TITLE"] = "Fixes"
L["WN45_7_TEXT"] = "On retail a moonkin druid saw two mana bars; only ours shows now, under Astral Power. The spellbook's Professions page slides back when another window closes, and on retail the crafting window opens beside the spellbook, not over it, with its border under the Create row; its expand button is gone, as the game's page is reached from the recipe. The group finder eye stays on the minimap's rim through Edit Mode, and on retail Shift-drag slides it round the rim. The micro menu's Edit Mode box no longer flashes in the corner, a micro button's alert pulses the 1.x glow, friendly nameplates no longer flash purple on retail, a Collections preview opens framed, Toggle none unchecks the windows under a parent, Loot rolls is on by default for new installs, and the options search keeps the rows above a match bright."
L["WN44_1_TITLE"] = "Themes in one color"
L["WN44_1_TEXT"] = "Themes now draw everything in one even color by default, as a dark mode does. To bring textures back for the parts you pick, turn on Textured color in the options (/fcui), under Look; the Themed drop down picks which parts take the theme at all. Parchment takes the theme too, with light text on a dark page. If you used a theme before, your look is kept."
L["WN44_2_TITLE"] = "Classic coins"
L["WN44_2_TEXT"] = "Gold, silver and copper show Era's round coins in your bags, at vendors, in mail, quests and tooltips. Uncheck Classic coins in the options (/fcui), under Look, for the modern ones."
L["WN44_3_TITLE"] = "One bar"
L["WN44_3_TEXT"] = "One bar now hides the latency bar and puts the key ring with the bags through their own options, so either can come back. Modern page arrows shows the game's small page arrows on the left gryphon; it is off by default, so turn it on in the options, under One bar."
L["WN44_4_TITLE"] = "Bags"
L["WN44_4_TEXT"] = "Hide quality borders and Hide junk coin take the colored quality borders and a vendor's gold coin off your items. Both are off by default, so turn them on in the options, under Bags."
L["WN44_5_TITLE"] = "Minimap"
L["WN44_5_TEXT"] = "Hide button borders has a Buttons drop down to pick which buttons lose their rings, each addon's minimap button can have its own pick, and the group finder eye stays on the minimap's rim."
L["WN44_6_TITLE"] = "Fixes"
L["WN44_6_TEXT"] = "A clicked nameplate keeps its yellow name while the mouse is on it. An option hides the tracker's All Objectives header, the options have an All windows page, and stat pane picks follow profiles."
L["WN43_1_TITLE"] = "Square minimap"
L["WN43_1_TEXT"] = "Square minimap makes the map square, in the round border's metal, with the buttons on its rim along the edge. It is off by default, so turn it on in the options (/fcui), under Minimap. While the game's Rotate Minimap is on, the map stays round."
L["WN43_2_TITLE"] = "Minimap"
L["WN43_2_TEXT"] = "Minimap close button puts Era's X on the zone bar: one click hides the map, another brings it back. It is off by default, so turn it on in the options, under Minimap. Edit mode's Header Underneath now moves the zone bar under the map, the clock sits at Era's spot in Era's plate, and Shift to drag minimap buttons can be turned off for a plain drag."
L["WN43_3_TITLE"] = "Nameplates"
L["WN43_3_TEXT"] = "The game's health numbers on our plates can sit on the right, split or on the left: pick one under Nameplates in the options (/fcui). Our plates now show the numbers the game's own Nameplate Information options pick, and the name of the plate under the mouse turns yellow, as on Classic Era."
L["WN43_4_TITLE"] = "Level-up banner"
L["WN43_4_TEXT"] = "The game's big level-up banner is hidden now, as 1.x had none. To see it again, turn on Level-up banner in the options (/fcui), under Other."
L["WN43_5_TITLE"] = "Windows"
L["WN43_5_TEXT"] = "The macro window and its icon picker take Era's look. On the character sheet the stat boxes take Era's gray rim, each character keeps its own stat pane picks, and the Statistics tab's sub headers use the classic plus and minus. Clicking Default toggles in the options now makes Classic-sized bars turn on too; a chat line says how to undo it."
L["WN43_6_TITLE"] = "Fixes"
L["WN43_6_TEXT"] = "On target and focus with thick health bars, incoming heals fill the whole bar and start right where the health ends. The map's Show Quest Levels filter no longer works backwards. Bar 1's dividers stay faded under the mouse, a quest object's page no longer runs past its parchment, with button borders hidden the calendar's ring comes off and the tracking glass sits centered, and grayed options show their tooltip again."
L["WN42_1_TITLE"] = "Minimap"
L["WN42_1_TEXT"] = "Other addons' minimap buttons, and our options button, can be shown, shown on hover or hidden without collecting them: Addon buttons, under Minimap in the options (/fcui). The tracking icon is one drop down too: shown, on hover or hidden. Hide the N (north) takes the N off the top of the minimap's rim; it is off by default, so turn it on under Minimap in the options. With the calendar behind day and night, hovering that icon shows the calendar in its place."
L["WN42_2_TITLE"] = "Chat"
L["WN42_2_TEXT"] = "The chat tabs and the frame round the typing box can each be shown, shown on hover or hidden: Chat tabs and Typing box frame, under Chat in the options (/fcui). Show them on hover, under Hide chat buttons, brings the hidden buttons back while the mouse is over the chat; it is off by default, so turn it on there in the options."
L["WN42_3_TITLE"] = "Bags"
L["WN42_3_TEXT"] = "The bag bar's options are on the Bags page now. Hide key ring art too, under Hide bags bar art, takes the key ring's art away with the bags' while the key ring is off the bar; it is off by default, so turn it on in the options (/fcui), under Bags. With the bag bar on backpack only and folded, the reagent bag stays and the key ring comes back on hover. In the one bag, hovering a bag button lights its slots again, the key ring's too."
L["WN42_4_TITLE"] = "Fading on hover"
L["WN42_4_TEXT"] = "Anything set to show on hover now fades in and out briefly instead of popping on and off."
L["WN42_5_TITLE"] = "Fixes"
L["WN42_5_TEXT"] = "With Profession windows off, the professions book no longer shows a dark box past its edge. Turning an option on our pages in the game's settings no longer puts our window's border over the game's window, and those pages run down to its foot; the options page also keeps its scroll spot. Menus and submenus get the classic look before they show. The Collections window keeps its filters, and with a window mover addon, the professions book's full size works and the spellbook no longer jumps."
L["WN41_1_TITLE"] = "One bag"
L["WN41_1_TEXT"] = "Turning on the bag slots row in the one bag no longer breaks the bag's layout with an error, and with sections by bag type the key ring's slots get a section of their own."
L["WN41_2_TITLE"] = "Spellbook key"
L["WN41_2_TEXT"] = "The spellbook key and button open the spellbook again, instead of the profession or Collections page shown last."
L["WN40_1_TITLE"] = "Collections window"
L["WN40_1_TEXT"] = "Mounts, pets, toys, heirlooms and appearances in a classic window on side tabs, with the game's own model views, a search box and one Filter menu. It opens from the Collections button or key and, with that micro button hidden, from a Collections tab at the foot of the spellbook, as a page of the book. On by default; Collections window, under Other in the options (/fcui), turns it off, and Collections tab under Spellbook hides the tab."
L["WN40_2_TITLE"] = "One bar"
L["WN40_2_TEXT"] = "With One bar on, Main bar alone takes the page arrows and the latency bar off it and puts the key ring with the bags. Turning One bar on now also hides the bag, micro menu and key ring art, stands the bag buttons close together and sets the micro menu in the screen's corner with the bags on it. One bar is off by default; turn it on in the options (/fcui), under Action bars, where Key ring with the bags and Bags close together are boxes of their own too."
L["WN40_3_TITLE"] = "Classic style windows"
L["WN40_3_TEXT"] = "Window frames is now Classic style windows, on the Look page of the options: one switch, with a box per window under it in a scrolling list with a search. While it is off, the window options on the other pages gray out and their tip says what to turn on. Turning it, or one window's box, off or on asks for a reload, since an open window keeps the frame it was built with."
L["WN40_4_TITLE"] = "Edit mode"
L["WN40_4_TEXT"] = "The totem bar has the stance bar's settings in edit mode: orientation, rows, icon size and padding. Buffs On Top is in the focus and pet frames' dialogs too, and the small focus frame shows its debuffs above as well. The buff arrow is one drop down in the options now: shown, on hover or hidden."
L["WN40_5_TITLE"] = "One bag"
L["WN40_5_TEXT"] = "One bag can show sections by bag type or by bag, the key ring's slots after the last bag's, in the key ring's brass (the key ring button then opens the one bag), and the equipped bag slots. Each is a box under One bag in the options (/fcui), under Bags, and off by default; turn it on there."
L["WN40_6_TITLE"] = "Spellbook pages and the map"
L["WN40_6_TEXT"] = "Professions and Collections count as pages of the spellbook: its button stays pressed on them, its key closes the page, and the book reopens on the page last shown. The classic world map opens at the game's map height in a window and keeps its size and spot through a fight."
L["WN40_7_TITLE"] = "Unit frames and the XP bar"
L["WN40_7_TEXT"] = "Enemy players' thick health bars show their class color, on by default (Enemy players too, under Class colored health). Elite frames picks Players and NPCs apart, so each keeps or themes its dragon. The XP bar's tooltip can say how much rested XP is left: Rested XP in the XP bar's tooltip, under Action bars, off by default; turn it on in the options (/fcui)."
L["WN40_8_TITLE"] = "Fixes"
L["WN40_8_TEXT"] = "Right-clicking a unit frame's power bar opens its menu again, Cyrillic names show on the unit frames and nameplates, Threat percent off hides the game's own number too, a quest clicked in a tracker addon opens our quest log, and a minimap button hidden by its own addon stays hidden. The professions book's full size is the classic book drawn bigger. A game window whose classic look is off is left to the game and other addons, nothing of ours on it, and the map's unlock box grays then. Inspecting a player always shows the character and PvP tabs. Default toggles (once Reset toggles) counts classic-sized bars as the default with our layout. Nameplate crowd control icons, the druid mana glow, the game menu's box, long client menus and the edit mode boxes got small fixes."
L["WN39_1_TITLE"] = "Era map markers"
L["WN39_1_TEXT"] = "On the Kalimdor and Eastern Kingdoms maps, capitals show Era's gray tower and towns its yellow house again, with the town's name on hover. It is on by default; Era city and town markers, under Map in the options (/fcui), turns it off."
L["WN39_2_TITLE"] = "Other action bar addons"
L["WN39_2_TEXT"] = "When another addon takes over the action bars, the classic bar steps aside instead of drawing under them. A popup says so once, and a chat line at each login until you turn off Bar takeover warning, under Addon messages in the options. Addon messages now quiets the welcome note too."
L["WN39_3_TITLE"] = "Damage flash"
L["WN39_3_TEXT"] = "The player frame no longer flashes the health you just lost in red, as 1.x never did. Off by default; to bring it back, turn it on in the options (/fcui): Damage flash, under Unit frames."
L["WN39_4_TITLE"] = "Window mover addons"
L["WN39_4_TEXT"] = "Leave game windows to other addons stops placing, sizing and locking the game's own windows, so a window mover addon can have them; ours keep their lock. Off by default; turn it on in the options, under Other. A new FAQ question says why a window mover moves some windows and not others."
L["WN39_5_TITLE"] = "Fixes"
L["WN39_5_TEXT"] = "Bag bar on hover shows the bags while the mouse is anywhere over the row, gaps between bags included, and the reagent bag's own hover no longer fades it off the classic bar. The classic map opened in a fight gets its classic size and spot at once, Escape works again after a profession window, and turning an action bar on or off lays the classic bar out again at once."
L["WN38_1_TITLE"] = "Minimap"
L["WN38_1_TEXT"] = "After the game's latest update, the minimap's tracking button and zone bar show their 1.x art again, and the zone name is back to Era's size. The game no longer shows a difficulty flag there, so its choice is gone from the options."
L["WN38_2_TITLE"] = "Fixes"
L["WN38_2_TEXT"] = "Attacking no longer sets off a damage meter error naming ClassicUI Forever, even with the damage meter off, and a fight no longer sets off a blocked action error about the bag bar."
L["WN37_1_TITLE"] = "Options in two panes"
L["WN37_1_TEXT"] = "The options (/fcui) list their pages on the left, with the search, and show the page on the right. Toggle none and Reset toggles work per page or for all, and Reset windows puts every window back to its own size and spot."
L["WN37_2_TITLE"] = "Bag bar"
L["WN37_2_TEXT"] = "Pick Bag bar in the options (/fcui), under Bag windows: hidden, shown only until bags are open or on hover, or backpack only, where a small arrow beside the backpack, seen while the mouse is over it, unfolds the bags."
L["WN37_3_TITLE"] = "Bar 2 beside bar 1"
L["WN37_3_TEXT"] = "Pick Bar 2: right of bar 1 on the band, or left, in the options (/fcui), under Classic bar: bar 2 at its default spot continues the band's stone sockets beside bar 1, with the rest of the band after both."
L["WN37_4_TITLE"] = "Spellbook options menu"
L["WN37_4_TEXT"] = "The spellbook's search row has an options menu: Hide passives, Group similar spells on flyouts (they drag to the bars in a fight too) and Show all spell ranks. Turn them on there, or in the options (/fcui) under Spellbook."
L["WN37_5_TITLE"] = "Fixes"
L["WN37_5_TEXT"] = "A pet's attacks and commands drag from the pet tab in a fight. The spellbook no longer flies off after a fight with the loot window open, a profession window opened in a fight shows its boxes, dragging the map with a map addon keeps the map, and the nameplate hover glow clears when the mouse leaves. Seven new questions in the FAQ."
L["WN37_6_TITLE"] = "Windows"
L["WN37_6_TEXT"] = "Game windows a window mover holds are left to it. One game window closes another only when both are of the kind Era closed, the rest stay put while one is dragged or sized out of the row, and a reset puts a game window back on its slot."
L["WN36_1_TITLE"] = "Legacy trees side by side"
L["WN36_1_TEXT"] = "Turn on Three trees side by side in the options (/fcui), under Legacy window, to see the Legacy window's three trees at once, with one Apply for all of them."
L["WN36_2_TITLE"] = "Minimap buttons press"
L["WN36_2_TEXT"] = "The addon's minimap buttons, the addon buttons bag and the group finder eye sink while you hold the mouse on them, as in Era."
L["WN36_3_TITLE"] = "Fixes"
L["WN36_3_TEXT"] = "Channeled spells show a green cast bar and the breath bar is see-through again, as in Era. The character window's tabs sink when pressed, the quest log's count has white numbers, and the world map's quest headers stay gold. The addon buttons bag no longer draws icons dark, and buttons join it at once after login."
L["WN36_4_TITLE"] = "Legacy button"
L["WN36_4_TEXT"] = "The Legacy button no longer stays pressed after its window closes, and the Legacy icon on the minimap opens its window again."
L["WN35_1_TITLE"] = "Three talent trees"
L["WN35_1_TEXT"] = "Turn on Three trees side by side in the options (/fcui), under Talent window, to see all three trees at once. Its Height drop down picks whether each tree scrolls, the window grows or the rows sit closer."
L["WN35_2_TITLE"] = "Double pane professions"
L["WN35_2_TEXT"] = "Turn on Double pane in the options (/fcui), under Profession windows, for a wider window: the recipes on the left, the chosen recipe and its reagents beside them."
L["WN35_3_TITLE"] = "Reagent bag in the one bag"
L["WN35_3_TEXT"] = "Turn on Reagent bag in the one bag in the options (/fcui), under Bag windows, and its slots open with the one bag like any other bag's, first or last, tinted green if you like. Hover the reagent bag button to light them."
L["WN35_4_TITLE"] = "Spellbook tabs"
L["WN35_4_TEXT"] = "The spellbook's tabs stand in Era's order for every class: a mage's read Arcane, Fire, Frost."
L["WN35_5_TITLE"] = "Fixes"
L["WN35_5_TEXT"] = "Combo points draw over the target's PvP flag, as in Era. Nameplates no longer cause Lua errors in dungeons. The social key opens the addon's social window again with the guild roster off, and the addon's windows line up with addons that center the game's windows."
L["WN35_6_TITLE"] = "Also on retail"
L["WN35_6_TEXT"] = "The Who page no longer shows the group finder's side tabs, which open WoW Forever's group finder."
L["WN34_1_TITLE"] = "Window placement"
L["WN34_1_TEXT"] = "The addon's windows open in one row after the game's windows, in the order you open them, and line up with addons that move the game's windows. A window you moved stays where you put it. With no room left, the oldest one closes, never in a fight."
L["WN34_2_TITLE"] = "Spellbook and talents"
L["WN34_2_TEXT"] = "The game's large spellbook and talent window closes when you open one of the addon's windows with no room beside it, as the game does with its own windows."
L["WN34_3_TITLE"] = "Resize grip"
L["WN34_3_TEXT"] = "While a window is unlocked, drag the grip in its bottom right corner to size it, or right-click the grip for its default size."
L["WN34_4_TITLE"] = "Group finder eye"
L["WN34_4_TEXT"] = "The eye is placed and sized in the game's Edit Mode again, with Snap to minimap and Show when not queued in its dialog."
L["WN34_5_TITLE"] = "Hide locked slots"
L["WN34_5_TEXT"] = "Without an authenticator on your account, turn on Hide locked slots in the options (/fcui), under Bag windows, and the backpack shrinks to the slots you can use."
L["WN34_6_TITLE"] = "Map and stats"
L["WN34_6_TEXT"] = "Maximized, the world map keeps its Era look, scaled to the screen. The Damage tooltip shows each hand's attack speed and damage per second, as in Era."
L["WN34_7_TITLE"] = "Also on Forever"
L["WN34_7_TEXT"] = "The classic world map shows your coordinates and the cursor's on one line in its footer. The pet tab shows Era's Attack, Attack Power, Damage, Defense and Armor rows."
L["WN33_1_TITLE"] = "Friend Requests"
L["WN33_1_TEXT"] = "The friends page's tabs are Friends, Recent Allies and Friend Requests. Battle.net friend requests wait on their own tab, counted in its name: pick one and Accept or Decline. The ignore list is in the drop down beside your Battle.net name."
L["WN33_2_TITLE"] = "Communities as a button"
L["WN33_2_TEXT"] = "Off by default: turn on Communities as a button in the options (/fcui), under Guild roster. Communities then leaves the tab row for a round button on the Guild page, and the four tabs keep their 1.x widths. Without a guild, a Communities tab stands in the Guild tab's place."
L["WN33_3_TITLE"] = "Update notice"
L["WN33_3_TEXT"] = "When someone in your guild or group has a newer ClassicUI Forever, one line in chat says so, with a link to CurseForge. Addon messages, under Other in the options, turns it off along with the addon's other chat lines."
L["WN33_4_TITLE"] = "Smoother stance changes"
L["WN33_4_TEXT"] = "Rogue stealth, druid forms and other stance changes no longer cause a micro stutter, and the quest tracker no longer jumps when they happen."
L["WN33_5_TITLE"] = "PvP details"
L["WN33_5_TEXT"] = "The PvP tab's details panel is laid out like the game's, in 1.x pieces: a line under your rank, the next rewards heading in an iron box and the reward's icon in an item slot."
L["WN33_6_TITLE"] = "Pet tab"
L["WN33_6_TEXT"] = "The pet tab shows your pet's training points, and its XP bar shows its numbers all the time, as in Era. Summoning your pet with the character window open no longer shows the pet in your place."
L["WN33_7_TITLE"] = "Fixes"
L["WN33_7_TEXT"] = "Stance, pet and possess buttons follow the theme. The social and character tab rows fit long languages like German, no label cut. Reputation rows light up under the mouse as in Era, and the loot window opens past your open windows. The addon's chat lines start with its gryphon."
L["WN32_1_TITLE"] = "Era's world map"
L["WN32_1_TEXT"] = "The world map shows Era's large map frame by default, with Continent and Zone drop downs and Zoom Out in its header. Each style draws the map at its own size; resize it any time in ClassicUI Forever Windows (edit mode). For the small map as before, turn on Navigation bar: none in the options (/fcui), under World map."
L["WN32_2_TITLE"] = "Map Options"
L["WN32_2_TEXT"] = "A Map Options box at the bottom right of the classic world map picks what the map shows. Show it always, on hover or never in the options, under World map."
L["WN32_3_TITLE"] = "Era's nameplate cast bar"
L["WN32_3_TEXT"] = "Nameplate cast bars take Era's look, the spell's icon in the bar's left slot. The plate you target or point at brightens, and a cast that cannot be interrupted keeps its icon under Era's shield. For the old cast bar, turn on Cast bar: icon beside it in the options, under Nameplates."
L["WN32_4_TITLE"] = "Free bag slots"
L["WN32_4_TEXT"] = "The backpack's free slot count follows the game's Show Free Bag Space, under Interface in the game's options, as in Era: off unless you check it, and never shown twice."
L["WN32_5_TITLE"] = "Fixes"
L["WN32_5_TEXT"] = "Hide button borders covers the minimap's day and night and zoom buttons too, with no extra ring when turned off. In ClassicUI Forever Windows (edit mode), the boxes of closed windows show where the windows sit, and Reset position puts the world map back on the game's own spot. The talents window's Apply button fits its text in every language. New installs open the quest log in its double pane."
L["WN31_1_TITLE"] = "Era's trade skill window"
L["WN31_1_TEXT"] = "The trade skill window takes Era's size, art and layout, with a filter by the kind of item made and recipe details that scroll when the reagents run long."
L["WN31_2_TITLE"] = "Professions book"
L["WN31_2_TEXT"] = "The professions book sits on the spellbook's parchment, each profession's emblem kept. The tabs beside the professions window show on hover; pick always shown or hidden in the options (/fcui), under Professions book. For the banded page, turn on Cataclysm-style book there."
L["WN31_3_TITLE"] = "Bags and key ring"
L["WN31_3_TEXT"] = "The bags on the bar follow edit mode's orientation and direction, so Vertical stands them in a column. The key ring can lie on its side as well: check Horizontal in its edit mode dialog."
L["WN31_4_TITLE"] = "More of Era's look"
L["WN31_4_TEXT"] = "Books and letters open in Era's reading window, every minimap button wears Era's stone ring, and popup text boxes and the social window's contacts button take Era's shapes."
L["WN31_5_TITLE"] = "Theme colors"
L["WN31_5_TEXT"] = "With a custom theme, more art takes its color, such as the list and scroll borders in most windows, the small world map and the minimap's day and night ring."
L["WN31_6_TITLE"] = "Options"
L["WN31_6_TEXT"] = "A Max camera distance slider in the options (/fcui), under Other, lets the camera pull back as far as 4.0. Only show matches, by the options search, lists just the options that match."
L["WN31_7_TITLE"] = "Fixes"
L["WN31_7_TEXT"] = "Looting no longer closes your open windows, bags on the bar no longer show a silver border, and a reinstall on the classic layout no longer brings back the game-sized bars. A name cut short in the who list shows in full when you point at it, and Train grays out for a new profession when both profession slots are taken, as in Era. Profession bars no longer show two greens, and the friends button by the chat no longer opens the game's social window."
L["WN31_8_TITLE"] = "Also on Forever"
L["WN31_8_TEXT"] = "The character window has Era's ammo slot with its arrow to the ranged slot, and the Looking For Group window shows Era's eye, turning while you are listed. The spellbook opened in a fight from its Professions tab no longer opens off to the side, the Legacy window's art no longer shifts between its pages, and the professions book's icons no longer jump around during a craft. The Skills tab's bars take Era's size and spacing, with Era's gold border under the mouse."
L["WN31_9_TITLE"] = "Group finder eye and tracking icon"
L["WN31_9_TEXT"] = "The group finder icon and the game's queue eye are one button: queued, the eye takes the icon's spot in Era's look and turns as Era's does. The tracking icon has Era's larger ring; to keep the old size, turn on Tracking icon: same size as other buttons in the options (/fcui), under Minimap."
L["WN31_10_TITLE"] = "Other addons on the minimap"
L["WN31_10_TEXT"] = "Addons that gather minimap buttons into a bag leave the group finder eye and the other minimap icons on the ring, and the options button shows its gryphon in their bag. Another addon's square minimap border no longer shows around the round minimap."
L["WN30_1_TITLE"] = "Action bar fixes"
L["WN30_1_TEXT"] = "Gold dividers no longer flash between the main bar's buttons when it changes page, as with Stealth or druid forms, and a toggled ability's gold border shows whole again."
L["WN30_2_TITLE"] = "Trainer"
L["WN30_2_TEXT"] = "Train in the classic trainer window learns the picked skill or recipe again, and your money below it shows at full brightness."
L["WN29_1_TITLE"] = "A classic Legacy window"
L["WN29_1_TEXT"] = "The Legacy button and key open a classic Legacy window: the reward track and the challenges on old skill bars, with a search and a filter, and the Legacy trees in the old talent window. On by default; turn it off in the options (/fcui), under Character and spells."
L["WN29_2_TITLE"] = "Your own layouts stay yours"
L["WN29_2_TEXT"] = "With the addon turned off, the action bars on your own edit mode layouts no longer sit at the classic bar's spots. Spots saved there before are handed back the next time you press Reload UI in the options (/fcui) or type /fcui off."
L["WN29_3_TITLE"] = "Fixes"
L["WN29_3_TEXT"] = "/fcui off turns the addon off again. Clicking a guild member in a fight opens their details. The game's settings window no longer floods errors after a fight, quest levels stay hidden with the option off, and the chat's scroll-to-bottom arrow no longer flashes in."
L["WN29_4_TITLE"] = "Weapon slots"
L["WN29_4_TEXT"] = "The character window's weapon slots sit centered on two wells, without the empty ranged slot well."
L["WN28_1_TITLE"] = "Recent Allies and Ignore"
L["WN28_1_TEXT"] = "The social window's Friends tab has Recent Allies and Ignore tabs beside Friends. Recent Allies lists the players you grouped with lately and has a search line; Ignore lists the players you ignore."
L["WN28_2_TITLE"] = "The classic social window again"
L["WN28_2_TEXT"] = "After the latest game update, O and the guild button opened the game's new social window. They open the classic one again, its tabs line up, and the Raid tab is back."
L["WN28_3_TITLE"] = "Fixes after the game update"
L["WN28_3_TEXT"] = "Combo points show all five classic orbs again. The dark strip over the character model and the dark box on the group finder's listing pages are gone, the sort button works in one-bag mode, and the group finder no longer jumps when opened in a fight."
L["WN28_4_TITLE"] = "Loot window and bags"
L["WN28_4_TEXT"] = "With Loot Window off, the game's loot window no longer shows two white squares in its corners. The bags' sort button fits beside the search box."
L["WN27_1_TITLE"] = "Less background work"
L["WN27_1_TEXT"] = "The nameplates are laid out again only when a nameplate setting changes, not on every setting the game or another addon changes. The minimap coordinates are measured only when they change. Nothing looks different."
L["WN26_1_TITLE"] ="Class colors per frame"
L["WN26_1_TEXT"] = "Class colored health and Class colored name box are off by default; turn them on in the options (/fcui), under Unit frames. Each now has a Frames drop-down under it: Player, Target and Focus, so the target can wear its class color while your own frame stays as it was."
L["WN26_2_TITLE"] = "Name box color"
L["WN26_2_TEXT"] = "A new Name box color drop-down under Unit frames picks which frames' name box takes the game's color for the unit (blue for a friendly player). Target and Focus are checked, as in Classic Era; uncheck one for a plain box. Player is off by default; turn it on in the options (/fcui) to color your own."
L["WN26_3_TITLE"] = "Fixes"
L["WN26_3_TEXT"] = "With thick health over the name, the player frame's name box no longer shows behind the bar. Unchecking the class colored name box clears it from the target and focus at once."
L["WN25_1_TITLE"] = "Gryphons"
L["WN25_1_TEXT"] = "The gryphons are now saved with the edit mode layout, like the game's own pieces: each layout keeps its own places for them, and Save on a game preset asks for a new layout, which takes them. A move left unsaved is dropped when edit mode closes. The classic layout in the options puts them back on the ends of the bar."
L["WN24_1_TITLE"] = "Bags"
L["WN24_1_TEXT"] = "Open bags no longer jump sideways when you right-click an item to equip it, in or out of a fight."
L["WN23_1_TITLE"] = "Swing timers"
L["WN23_1_TEXT"] = "Changing a weapon in a fight no longer sets off a Lua error on every frame the swing bar shows, and the flash as a swing lands keeps working after the change."
L["WN22_1_TITLE"] = "Professions"
L["WN22_1_TEXT"] = "A profession opens in the classic trade skill window, and the professions book is the old small one in the spellbook's frame. The size button beside the close button switches either to the game's full window."
L["WN22_2_TITLE"] = "Spellbook and talents"
L["WN22_2_TEXT"] = "A spellbook button on the micro menu, beside the character button, opens the classic spellbook. The game's talent window wears the classic frame, and the talents button always opens it on your talents."
L["WN22_3_TITLE"] = "Micro menu and minimap"
L["WN22_3_TEXT"] = "Achievements, Adventure Guide and Housing are off the micro menu, as 1.x had none, and each has an icon on the minimap. To bring a button back, uncheck it under Hide micro buttons in the options (/fcui)."
L["WN22_4_TITLE"] = "Quick Join"
L["WN22_4_TEXT"] = "Quick Join left the social window's tab row. Open Friends, then Recent Allies: the Quick Join tab under the list swaps to it, and the Recent Allies tab swaps back."
L["WN22_5_TITLE"] = "Performance"
L["WN22_5_TEXT"] = "Color themes use far less CPU: the colored art now follows the game's only when something changes, not every frame. Right-click menus on portraits, bags and windows open without a stutter."
L["WN22_6_TITLE"] = "Macros"
L["WN22_6_TEXT"] = "A spell shift-clicked from the classic spellbook into a macro goes in by name and rank, as from the game's book; it went in as a chat link, which a macro cannot cast. The macro window has Classic Era's tabs."
L["WN22_7_TITLE"] = "Macros"
L["WN22_7_TEXT"] = "A spell shift-clicked from the classic spellbook into a macro goes in by name and rank, as from the game's book; it went in as a chat link, which a macro cannot cast. A talent goes in by name too. The macro window has Classic Era's tabs."
L["WN22_8_TITLE"] = "Drop-down menus"
L["WN22_8_TEXT"] = "The game's drop-down menus, such as the status menu (Available, Away, Busy) and the minimap's tracking menu, now have Classic Era's iron frame, and it holds their icons and arrows."
L["WN22_9_TITLE"] = "Reputation and currency"
L["WN22_9_TEXT"] = "Both tabs keep the classic rows: even spacing, the old headers, one column of bars. A group of factions has its plus or minus button with its factions indented under it, and the filter is a small arrow button at the top right."
L["WN22_10_TITLE"] = "Other fixes"
L["WN22_10_TEXT"] = "The tabs under a window stay on its bottom border; at some interface sizes they climbed. Shift-clicking a profession leaves the spellbook open, a druid's form mana numbers follow the game's Status Text setting, and the Help tab lists only the questions for the game version you play."
L["WN22_11_TITLE"] = "Retail windows"
L["WN22_11_TEXT"] = "The reagent bag stands clear of the latency bar, the character window has no thin lines round the model, the social window has one Who tab, and window borders line up as on Forever."
L["WN21_1_TITLE"] = "Guild roster"
L["WN21_1_TEXT"] = "Clicking a member opens their notes and options for every member; in larger guilds many members opened nothing. The roster also uses far less CPU while it is open."
L["WN21_2_TITLE"] = "Quest sharing"
L["WN21_2_TEXT"] = "Share Quest in the classic quest log works for any quest in one press, right after logging in too. It worked only for quests of the zone the world map last showed."
L["WN21_3_TITLE"] = "Windows"
L["WN21_3_TEXT"] = "An opened letter has the classic window frame, as the inbox does, and the character window's side panel no longer shows a thin see-through line at some interface sizes."
L["WN20_1_TITLE"] ="PvP rank details"
L["WN20_1_TEXT"] = "The PvP tab of the character window can show your rank details and the next rank's rewards. Click the arrow at the bottom right of the tab to open the side panel."
L["WN20_2_TITLE"] = "Addon button bag"
L["WN20_2_TEXT"] = "Its default spot is now left of the clock, clear of the group finder eye, and it leaves our own minimap icons such as Legacy on the minimap. The Classic layout button also puts dragged minimap buttons back."
L["WN20_3_TITLE"] = "Other addons"
L["WN20_3_TEXT"] = "Parts of ClassicUI Forever that you turn off now leave the game's frames alone, so addons that restyle them keep their look."
L["WN19_1_TITLE"] = "Minimap icons"
L["WN19_1_TEXT"] = "Any micro button can now sit on the minimap as an icon: check it under Micro buttons on the minimap in the options (/fcui). Legacy and the group finder are on by default, so Legacy has a way in again. Hold Shift and drag to move our minimap buttons around the ring."
L["WN19_2_TITLE"] = "Quest watch"
L["WN19_2_TEXT"] = "The objective tracker can be Classic Era's plain quest watch. Off by default; to turn it on, set Objective tracker to Classic Era watch in the options (/fcui), under Quests. Click a title to open the quest, shift-click to untrack it, right-click for more."
L["WN19_3_TITLE"] = "Options window"
L["WN19_3_TEXT"] = "The options window is larger, and its long lists are now drop-downs, so there is less to scroll."
L["WN19_4_TITLE"] = "Threat percent"
L["WN19_4_TEXT"] = "The threat percent can show only in a group or dungeon: turn on Only in a group or dungeon in the options (/fcui), under Unit frames. Off by default."
L["WN19_5_TITLE"] = "Classic Era touches"
L["WN19_5_TEXT"] = "The game menu button's tooltip has Classic Era's descriptions, drop-down menus use Classic Era's iron frame, and micro buttons no longer turn gray while the game menu is open."
L["WN19_6_TITLE"] = "Fixes"
L["WN19_6_TEXT"] = "Reset toggles keeps the classic-sized bars, custom themes color the options tabs fully, the classic bar's art stays shown on the ClassicUI Forever layout, the options button no longer overlaps the tracking magnifier, and with Minimap unchecked, minimap icons hidden by another addon stay hidden."
L["WN18_1_TITLE"] = "Professions"
L["WN18_1_TEXT"] = "The trade skill window can now track a recipe (its reagents show in the objective tracker), filter by gear slot, and link your profession in chat with the chain link beside its title. The professions key opens the professions book again."
L["WN18_2_TITLE"] = "Elite dragons"
L["WN18_2_TEXT"] = "Elite enemies can show a gold dragon around their level on the nameplate, rares a silver one: turn on Elite dragons in the options (/fcui), under Nameplates. With a custom theme on, Ignore theme for elite frames and Ignore theme for nameplate dragons, under Custom theme, keep the dragons gold and silver. All off by default."
L["WN18_3_TITLE"] = "Combat glow"
L["WN18_3_TEXT"] = "To stop the player frame's red pulse while you attack, turn on Hide combat glow in the options (/fcui), under Unit frames. Off by default."
L["WN18_4_TITLE"] = "Cast bars"
L["WN18_4_TEXT"] = "Interrupted casts on the target, focus and nameplates now turn red and say just Interrupted, as in Classic Era. To see who interrupted, turn on Name who interrupted in the options (/fcui), under Cast bars. Channels show green."
L["WN18_5_TITLE"] = "Instance difficulty"
L["WN18_5_TEXT"] = "The difficulty flag the game shows on the minimap in dungeons and raids is now hidden. To bring it back, pick shown or on hover under Minimap in the options (/fcui)."
L["WN18_6_TITLE"] = "Classic layout"
L["WN18_6_TEXT"] = "The durability figure no longer hides behind the side bars, and buffs sit at Classic Era's spots beside the minimap. The layout also offers Classic Era's interface size when yours is different."
L["WN18_7_TITLE"] = "Look"
L["WN18_7_TEXT"] = "Menus have Classic Era's black background, and nameplates match Classic Era's size. The empty part of the XP and reputation bars is shaded as in Classic Era; to turn the shade off, uncheck Shaded XP and reputation bars under Classic bar."
L["WN18_8_TITLE"] = "Fixes"
L["WN18_8_TEXT"] = "Train works for recipes far down a trainer's list. The chat buttons stay on every chat tab, and shift-click links a talent in chat. The world map opened in a fight no longer catches clicks, and Edit Mode's red buttons stay whole when you change theme."
L["WN17_1_TITLE"] = "Nameplate errors"
L["WN17_1_TEXT"] = "With a theme on, the classic nameplates no longer cause error messages."
L["WN17_2_TITLE"] = "Target buffs"
L["WN17_2_TEXT"] = "Buffs under the target and focus frames now appear in place when you change target, without the brief jump."
L["WN17_3_TITLE"] = "World map in a fight"
L["WN17_3_TEXT"] = "The classic world map opened in a fight now looks the same as out of combat."
L["WN16_1_TITLE"] = "Action icons"
L["WN16_1_TEXT"] = "With a theme on, action button icons no longer turn dark at random."
L["WN16_2_TITLE"] = "Combat glow"
L["WN16_2_TEXT"] = "With Thick health bars over the name, the red combat glow and the gold resting glow now light up the whole player frame instead of the health bar. Thick health bars are off by default; turn them on in the options (/fcui), under Unit frames."
L["WN16_3_TITLE"] = "Nameplates"
L["WN16_3_TEXT"] = "With the classic nameplates turned off, the game's own nameplates no longer cause error messages."
L["WN15_1_TITLE"] = "Threat"
L["WN15_1_TEXT"] = "Classic Era's threat percent now shows above the target and focus frames in a fight. The red glow around the unit frames is now hidden by default; to bring it back, uncheck Hide threat glow in the options (/fcui), under Unit frames."
L["WN15_2_TITLE"] = "Druid mana"
L["WN15_2_TEXT"] = "In bear and cat form, druids now see their mana in a small bar under the rage or energy bar."
L["WN15_3_TITLE"] = "Enemy health color"
L["WN15_3_TEXT"] = "Off by default. To use it, turn on Thick health bars in the options (/fcui), under Unit frames, then pick By reaction under Enemy health: neutral enemies get a yellow bar, hostile ones red."
L["WN15_4_TITLE"] = "English text"
L["WN15_4_TEXT"] = "For a game in another language: this add-on's own text can show in English, part by part. Off by default; turn it on in the options (/fcui), under Other, English text."
L["WN15_5_TITLE"] = "Who list"
L["WN15_5_TEXT"] = "The arrow at the top of the Who list's last column now holds the game's class, race and zone filters. A search with one or two results stays in the window instead of going to chat."
L["WN15_6_TITLE"] = "Flat color"
L["WN15_6_TEXT"] = "Flat color paints the window and bar art in one solid color instead of textured metal. It now keeps the thin lines inside windows, around lists, footers and dividers, unless you also turn on Hide inner borders. Both are off by default: turn on Custom theme, then Flat color, in the options (/fcui), under Look."
L["WN15_7_TITLE"] = "Swing timers"
L["WN15_7_TEXT"] = "The swing timers can now skip the flash after each swing: uncheck Flash as a swing lands in the options (/fcui), under Swing timers."
L["WN15_8_TITLE"] = "Nameplates"
L["WN15_8_TEXT"] = "Nameplate names and small numbers now use Classic Era's plain text. New and off by default: Same size near and far keeps every nameplate one size, as in Classic Era; turn it on in the options (/fcui), under Nameplates."
L["WN15_9_TITLE"] = "Windows"
L["WN15_9_TEXT"] = "Quest, gossip and vendor windows and the quest log list now have Classic Era's thin border around their content, and the character window shows your character's face on every tab."
L["WN15_10_TITLE"] = "Fixes"
L["WN15_10_TEXT"] = "With a theme on, icon rims, portrait rings, menus and the vendor's page arrows take its color, and sliders stay visible. The character window's tabs now click where they are drawn."
L["WN14_1_TITLE"] = "Controller"
L["WN14_1_TEXT"] = "With the gamepad interface on, the classic spellbook, talents and quest log open inside the game's own windows, so a controller can move through them."
L["WN14_2_TITLE"] = "Theme everywhere"
L["WN14_2_TEXT"] = "With a theme on, the game's own pieces take its color too where you left the classic ones off: minimap, unit frames, bars, windows and the game menu's buttons."
L["WN14_3_TITLE"] = "Darkness"
L["WN14_3_TEXT"] = "Dark has a slider from light gray to black, with a button back to the default."
L["WN14_4_TITLE"] = "Flat color"
L["WN14_4_TEXT"] = "Flat color (Custom theme) shows the parts you check in one flat color, in the same shapes."
L["WN14_5_TITLE"] = "Micro buttons"
L["WN14_5_TEXT"] = "Hide micro buttons now works on the game's own micro menu with the classic bar off, and can hide the Shop."
L["WN14_6_TITLE"] = "Bars 6 to 8"
L["WN14_6_TEXT"] = "Hide bars 6 to 8 is gone: the game's own action bar settings decide."
L["WN14_7_TITLE"] = "Fixes"
L["WN14_7_TEXT"] = "Hidden and on hover minimap coordinates work with the game's minimap, other add-ons' minimap buttons take the theme, and a hunter's backpack shows free bag slots instead of ammo."
L["WN13_1_TITLE"] = "Threat glow"
L["WN13_1_TEXT"] = "Hide threat glow (Unit frames) takes the red threat glow off the unit frames. The game's threat number stays."
L["WN13_2_TITLE"] = "Quest items"
L["WN13_2_TEXT"] = "Plain quest items (Bag windows) shows quest items in the bags and bank without the quest border."
L["WN13_3_TITLE"] = "Numbers"
L["WN13_3_TEXT"] = "Numbers without separators (Unit frames) drops the thousands separators from large numbers, on the bars and across the game."
L["WN13_4_TITLE"] = "Action icons"
L["WN13_4_TEXT"] = "With a theme on, action icons show whole again, as in Classic Era; only their own border takes the theme's color."
L["WN13_5_TITLE"] = "Your bars"
L["WN13_5_TEXT"] = "If 0.14.0 changed your bars, a chat line at login lets you put them back as they were or take the classic look."
L["WN13_6_TITLE"] = "Social window"
L["WN13_6_TEXT"] = "The Friends and Raid tabs sit in their thin border as in Classic Era, and the Raid tab's description shows again outside a raid."
L["WN13_7_TITLE"] = "Fixes"
L["WN13_7_TEXT"] = "Loot at the mouse opens with the first item under the cursor, tab labels turn white on hover, and Classic layout brings back the classic micro menu and bag slots."
L["WN12_1_TITLE"] = "Windows"
L["WN12_1_TEXT"] = "A lock and a reset sit beside each window's close button: unlock a window to drag it by its title. The quest and gossip windows, social window, group finder and professions book can be placed and sized in ClassicUI Forever Windows."
L["WN12_2_TITLE"] = "Swing timers"
L["WN12_2_TEXT"] = "The game's swing timers in the 1.x cast bar's look, with a color per hand and a flash on each swing. Pick the colors and Border thickness in the options."
L["WN12_3_TITLE"] = "Thick health bars"
L["WN12_3_TEXT"] = "A taller health bar on the player, target and focus frames, over the name or the mana (Unit frames). Class colored name box and Name size are new there too."
L["WN12_4_TITLE"] = "Gryphons"
L["WN12_4_TEXT"] = "Drag, size or hide the gryphons in the game's edit mode. With snapping on they line up with the bars and go back to their spot."
L["WN12_5_TITLE"] = "Damage meter"
L["WN12_5_TEXT"] = "The damage meter in the 1.x rim with classic buttons and a marble or talent tree background you can move."
L["WN12_6_TITLE"] = "Languages"
L["WN12_6_TEXT"] = "ClassicUI Forever is now in German, French, Spanish and Italian."
L["WN12_7_TITLE"] = "Options"
L["WN12_7_TEXT"] = "New FAQ and Support tabs, a Custom color for the theme, and a search that finds a setting by more of its names."
L["WN12_8_TITLE"] = "Resource display"
L["WN12_8_TEXT"] = "The personal resource display in 1.x bars and the old nameplate border, with a Bar gap setting."
L["WN12_9_TITLE"] = "Classic bar"
L["WN12_9_TEXT"] = "Classic-sized bag slots, every micro button can be hidden, the Help button is back at the end of the micro menu, and Band holds bars 2 and 3 keeps those bars on the band."
L["WN12_10_TITLE"] = "Minimap and chat"
L["WN12_10_TEXT"] = "Coordinates and a hideable border and header on the minimap, the group finder eye on it when its micro button is hidden, and each chat button can be hidden on its own."
L["WN12_11_TITLE"] = "Fixes"
L["WN12_11_TEXT"] = "Bars no longer jump to the top of the screen after an edit mode drag, bar 1 moves with the arrow keys in edit mode, the XP bar no longer shows twice after logging in during a fight, and loot pages no longer repeat items."
L["WN12_12_TITLE"] = "Smaller fixes"
L["WN12_12_TEXT"] = "Pet and party numbers fit their bars, the micro menu no longer jumps when dragged, the latency bar keeps its frame, and micro button tips show once with the right quest limit."
L["WN11_1_TITLE"] = "Chat"
L["WN11_1_TEXT"] = "Hide chat buttons lets the chat sit at the screen's edge, and Chat scroll bar keeps WoW Forever's scroll bar (Chat buttons)."
L["WN11_2_TITLE"] = "Quest levels"
L["WN11_2_TEXT"] = "Quest levels (Quests) shows each quest's level on the map, in the tracker and in the quest log, in step with the map's own filter."
L["WN11_3_TITLE"] = "Dark theme"
L["WN11_3_TEXT"] = "Right-click menus, addon minimap buttons, the zoom buttons, clock and day and night icon take the theme, and action icons show no light edge."
L["WN11_4_TITLE"] = "Fixes"
L["WN11_4_TEXT"] = "No double quest level in the tracker, no errors from right-click menus in dungeons, and the target's menu stays on screen."
L["WN10_1_TITLE"] = "Minimap"
L["WN10_1_TEXT"] = "Each minimap piece can show, show only on hover, or hide (Minimap in the options), and zoom in and out move around the ring on their own in ClassicUI Forever Windows."
L["WN10_2_TITLE"] = "Micro menu"
L["WN10_2_TEXT"] = "Classic Era's descriptions in the micro button tooltips, and Hide micro buttons takes single buttons off the menu (Classic bar)."
L["WN10_3_TITLE"] = "Key ring"
L["WN10_3_TEXT"] = "Opens with no keys, in its own window, in Classic Era's art."
L["WN10_4_TITLE"] = "New options"
L["WN10_4_TEXT"] = "Hide stance bar (Classic bar), Name text size (Nameplates) and Unit tooltip on bars (Unit frames)."
L["WN10_5_TITLE"] = "Fixes"
L["WN10_5_TEXT"] = "Scroll arrows gray out with nothing to scroll, the quest log highlights as in Classic Era, guild Last Online sorts properly and the macro window opens beside the spellbook."
L["WN10_6_TITLE"] = "Smaller fixes"
L["WN10_6_TEXT"] = "Talent arrows, the guild tab without a guild, page arrows over the map, the addon buttons bag and shorter layout prompts."
L["WN9_1_TITLE"] = "Classic world map"
L["WN9_1_TEXT"] = "Classic Era's small map, with the map's quest list in its own pane beside it and rewards after the quest text. Map navigation bar under Map in the options brings back the game's map layout."
L["WN9_2_TITLE"] = "New options"
L["WN9_2_TEXT"] = "Hide map quest button (Map), Classic-sized bars (Classic bar) and Shake on interrupt (Cast bars)."
L["WN9_3_TITLE"] = "Classic look"
L["WN9_3_TEXT"] = "Right-click menus, drop down lists, the social window, group finder, Who list and guild roster follow Classic Era; the settings window takes today's Classic Era client look, and the Ignore List and dressing room the classic look."
L["WN9_4_TITLE"] = "Edit mode"
L["WN9_4_TEXT"] = "The spellbook can be moved and sized in ClassicUI Forever Windows."
L["WN9_5_TITLE"] = "Bars and tracker"
L["WN9_5_TEXT"] = "Bars 4 and 5 keep their place at the screen's edge, and the quest tracker no longer sits over them."
L["WN9_6_TITLE"] = "Fixes"
L["WN9_6_TEXT"] = "Neutral NPCs show their level instead of a skull, and clicking a unit frame's bars targets again."
L["WN9_7_TITLE"] = "Windows and tabs"
L["WN9_7_TEXT"] = "Vendor, mail, guild charter and tabard windows, and many other windows and tabs, line up with Classic Era; Escape closes the guild charter window."
L["WN8_1_TITLE"] = "Gryphons over bars"
L["WN8_1_TEXT"] = "Check Gryphons over bars under Classic bar in the options to draw the gryphons in front of bars 2 and 3."
L["WN8_2_TITLE"] = "Windows open on key press"
L["WN8_2_TEXT"] = "The spellbook, professions, talents, guild and quest log keys and Escape act on the press, as the game's own windows do."
L["WN8_3_TITLE"] = "Fixes"
L["WN8_3_TEXT"] = "Spells drag onto Action Bar 1 again, the zone name is centered on the minimap bar wherever the calendar sits, and the spellbook's tabs and pet commands look right."
L["WN7_1_TITLE"] = "Classic key text"
L["WN7_1_TEXT"] = "Key names on the action buttons are Classic Era's size and outline. Key text size under Button style in the options makes them bigger or smaller."
L["WN7_2_TITLE"] = "Calendar spots"
L["WN7_2_TEXT"] = "The calendar is a small square by the zone name; put it on the ring or behind the day and night icon under Calendar button in the options. Check Calendar under Minimap in ClassicUI Forever Windows in edit mode to move or resize it."
L["WN6_1_TITLE"] = "Calendar button"
L["WN6_1_TEXT"] = "The calendar sits under the day and night icon on the minimap. To hide it, uncheck Calendar button under Minimap in the options."
L["WN5_1_TITLE"] = "Fixes"
L["WN5_1_TEXT"] = "The group finder's new player friendly flag lines up with the role icons. Details in the full changelog."
L["WN4_1_TITLE"] = "Fixes"
L["WN4_1_TEXT"] = "Tabs take the mouse on the tab itself, a profession cast from the spellbook closes the book in a fight, and the loot window's header is clean. Details in the full changelog."
L["WN3_1_TITLE"] = "Classic bar pieces"
L["WN3_1_TEXT"] = "Classic had no professions button and no reagent bag, so the professions button is off the micro menu (professions open from the spellbook) and the reagent bag is a small round button on hover. Bars 2 and 3 fit between the gryphons again. Both are rows under Classic bar in the options."
L["WN2_1_TITLE"] = "Windows edit mode"
L["WN2_1_TEXT"] = "Check Windows in edit mode to move and resize the character sheet, spellbook, talents, quest log, professions and map."
L["WN2_2_TITLE"] = "Profiles"
L["WN2_2_TEXT"] = "A Profiles tab in the options keeps named settings per character."
L["WN2_3_TITLE"] = "Bronze or Dark"
L["WN2_3_TEXT"] = "The custom theme comes in Forever's bronze or a dark charcoal. See the Custom theme toggle in the options."
L["WN2_4_TITLE"] = "Classic bar"
L["WN2_4_TEXT"] = "The bars are no longer reduced in size by default. The bar now carries the latency bar, key ring and reagent bag as classic did; each can be moved in edit mode or hidden under Classic bar in the options."
L["WN2_5_TITLE"] = "Minimap buttons"
L["WN2_5_TEXT"] = "Other addons' minimap buttons can gather behind one button on the ring. See the Collect addon buttons toggle in the options."
L["WN2_6_TITLE"] = "Options"
L["WN2_6_TEXT"] = "Quests and Map sections, and new rows for the map frame, loot window, loot rolls, hiding the game's tracker, the professions button and the key text."
L["WN2_7_TITLE"] = "Reset classic layout"
L["WN2_7_TEXT"] = "Puts the windows, tracker, gryphons, bar pieces and layout settings back at once."
